#pragma once
// Data generated by tools/build.py from characters/ and roster.toml.

#include "types.h"

#define ROSTER_MAX 48

struct RosterCharacter {
    const char *name;   // display name
    const char *suffix; // file suffix: st_kart-<suffix>.szs, <suffix>.brres
    const char *iconPane; // picture pane in character_64x64_common.brlyt
    u8 statsFrom;       // character ID whose stats are copied
    u8 isCustom;
};

extern const u32 rosterCount;                          // buttons on the select screen
extern const u8 rosterButtonToId[ROSTER_MAX];          // button index -> character ID
extern const struct RosterCharacter rosterById[ROSTER_MAX]; // character ID -> info
